<?php namespace App\Console\Commands; use Illuminate\Console\Command; use Illuminate\Support\Facades\{DB,File}; class LegacyAuditUsersCommand extends Command {protected $signature='legacy:audit-users {--out=docs/generated/users-audit}'; public function handle():int{$d=DB::connection('legacy_wp');$u=$d->table('users');$roles=[];foreach($d->table('usermeta')->where('meta_key','tp_capabilities')->get() as $m)foreach((array)@unserialize($m->meta_value,['allowed_classes'=>false]) as $r=>$v)if($v)$roles[$r]=($roles[$r]??0)+1;$r=['total'=>$u->count(),'roles'=>$roles,'empty_email'=>(clone $u)->where('user_email','')->count(),'hash_formats'=>(clone $u)->selectRaw("case when user_pass like '\$P\$%' then 'phpass' when user_pass like '\$wp\$2y\$%' then 'wordpress_bcrypt' else 'other' end format,count(*) count")->groupBy('format')->get(),'registration'=>(clone $u)->selectRaw('min(user_registered) oldest,max(user_registered) newest')->first(),'claims'=>$d->table('posts')->where('post_type','lp-claims')->count(),'claimed_listings'=>$d->table('postmeta')->where('meta_key','claimed')->count()];$b=base_path($this->option('out'));File::put($b.'.json',json_encode($r,JSON_PRETTY_PRINT));File::put($b.'.md','# Users Audit\n\n```json\n'.json_encode($r,JSON_PRETTY_PRINT).'\n```\n');$this->info('Users audit written.');return 0;}}
